// single-item input: one call from one workflow, one URL.
//
// Read the trigger by name: `Settings` sits between the two and a Set node in
// manual mode replaces the item, so $input here would be the config rather than
// what the caller passed.
const call = $('A Workflow Asks For A Page').first().json;
const cfg = $('Settings').first().json;

const url = String(call.url || '').trim();
if (!/^https?:\/\//i.test(url)) {
  throw new Error('Pass a full URL including https://. Received: ' + (url || '(nothing)'));
}

// markdown for prose, html when the caller needs tags, json when the target
// already returns JSON and the markdown converter would mangle it.
const allowed = ['markdown', 'html', 'json'];
let format = String(call.format || cfg.default_format || 'markdown').toLowerCase();
if (allowed.indexOf(format) === -1) format = 'markdown';

// 0 means "do not use the cache". Absent means use the default.
const maxAge = call.max_age_minutes === '' || call.max_age_minutes == null
  ? Number(cfg.default_max_age_minutes || 60)
  : Number(call.max_age_minutes);

return [{ json: {
  url,
  format,
  max_age_minutes: isNaN(maxAge) ? 60 : maxAge,
  // The markdown converter escapes JSON into something JSON.parse cannot read,
  // so `json` and `html` both mean "send it back raw".
  want_markdown: format === 'markdown',
  requested_at: $now.toISO(),
}}];

// Has anyone asked for this recently?
//
// The Data Table read has alwaysOutputData, so an empty cache emits one empty
// item rather than ending the branch - which on the very first call would mean
// nothing downstream ever ran and the cache was never written.
const req = $('Read The Request').first().json;
const rows = $input.all().map((x) => x.json).filter((r) => r && r.url);

const hit = rows.find((r) => r.url === req.url);

let fresh = false;
let ageMinutes = null;
if (hit && req.max_age_minutes > 0 && hit.fetched_at) {
  const then = Date.parse(hit.fetched_at);
  if (!isNaN(then)) {
    ageMinutes = Math.round((Date.now() - then) / 60000);
    fresh = ageMinutes <= req.max_age_minutes;
  }
}

// A cached row with no body is not a cache hit worth serving.
if (fresh && !(hit.content && hit.content.length)) fresh = false;

return [{ json: Object.assign({}, req, {
  cache_hit: !!hit,
  cache_fresh: fresh,
  cache_age_minutes: ageMinutes,
  cached_content: fresh ? hit.content : '',
  cached_status: fresh ? hit.status : '',
}) }];

// single-item input: one URL, one response.
//
// This is the check every caller would otherwise have to write. Bright Data
// answers a validation error, a blocked target or an exhausted zone with
// **HTTP 200 and an error body**, and the HTTP node runs with neverError, so
// nothing throws and a failure looks exactly like a successful empty page.
const req = $('Read The Request').first().json;
const raw = $input.first().json;

let body = typeof raw === 'string' ? raw : (raw.data != null ? raw.data : (raw.body != null ? raw.body : ''));
if (body && typeof body === 'object') body = JSON.stringify(body);
body = String(body || '');

// An error body is JSON with an `error` key, and it is short.
let bdError = '';
if (body.length < 2000 && /^\s*\{/.test(body)) {
  try {
    const j = JSON.parse(body);
    if (j && (j.error || j.error_message)) {
      bdError = String(j.error && j.error.message ? j.error.message : (j.error || j.error_message)).slice(0, 200);
    }
  } catch (e) { /* not an error envelope, just a JSON page */ }
}

// Measured 2026-08-23: a domain that does not resolve returns zero bytes.
const empty = body.length === 0;
// Thin but not empty is the signature of a page whose content is built in the
// browser - a shell of a document with the real thing behind JavaScript.
const thin = !empty && body.length < Number(300);

return [{ json: Object.assign({}, req, {
  content: body,
  bytes: body.length,
  bd_error: bdError,
  needs_browser: !bdError && (empty || thin),
  ok: !bdError && !empty && !thin,
}) }];

// single-item input: one rendered retry.
//
// Same checks as the first pass, but this is the last word - there is no third
// attempt, and a caller is better served by an honest failure than by a
// workflow that keeps trying.
const prev = $('Read What Came Back').first().json;
const raw = $input.first().json;

let body = typeof raw === 'string' ? raw : (raw.data != null ? raw.data : (raw.body != null ? raw.body : ''));
if (body && typeof body === 'object') body = JSON.stringify(body);
body = String(body || '');

let bdError = '';
if (body.length < 2000 && /^\s*\{/.test(body)) {
  try {
    const j = JSON.parse(body);
    if (j && (j.error || j.error_message)) {
      bdError = String(j.error && j.error.message ? j.error.message : (j.error || j.error_message)).slice(0, 200);
    }
  } catch (e) { /* not an error envelope */ }
}

const ok = !bdError && body.length >= 300;

return [{ json: Object.assign({}, prev, {
  content: ok ? body : prev.content,
  bytes: ok ? body.length : prev.bytes,
  bd_error: bdError || prev.bd_error,
  rendered: true,
  ok,
}) }];

// single-item input: one call asked for one URL, and exactly one of the three
// paths reaches here with it.
//
// One shape for the caller, whichever path got here.
//
// A sub-workflow that returns different fields depending on what happened is
// one every caller has to defend against. `ok`, `from_cache` and `error` are
// always present, so a caller can branch on the result rather than guess.
const req = $('Read The Request').first().json;

// Which of the three paths produced this item is exactly what $input knows.
const j = $input.first().json || {};
const fromCache = !!j.cache_fresh && !!j.cached_content;

const content = fromCache ? j.cached_content : String(j.content || '');
const ok = fromCache ? true : !!j.ok;

let error = '';
if (!ok) {
  if (j.bd_error) error = 'Bright Data returned an error: ' + j.bd_error;
  else if (!content) error = 'The URL returned nothing. The domain may not resolve.';
  else error = 'The page returned too little to be usable, even with a browser.';
}

return [{ json: {
  url: req.url,
  format: req.format,
  ok,
  from_cache: fromCache,
  cache_age_minutes: fromCache ? j.cache_age_minutes : null,
  rendered: !fromCache && !!j.rendered,
  bytes: content.length,
  content,
  error,
  fetched_at: fromCache ? (j.cached_status || req.requested_at) : req.requested_at,
}}];
